def filter_inventory(records, required_label):
    if not isinstance(required_label, str):
        raise TypeError("required_label must be a string")
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError("each record must be a dictionary")
        if "labels" not in record:
            raise ValueError("record is missing labels")
        labels = record["labels"]
        if not isinstance(labels, list) or not all(isinstance(label, str) for label in labels):
            raise TypeError("labels must be a list of strings")
        if required_label in labels:
            result.append(record)
    return result
